window.kbPageData["views/entry/k-62d38cae7836cb1c"] = {"key":"entry/k-62d38cae7836cb1c","state":{"route":"entry/k-62d38cae7836cb1c"},"node":{"id":"k-62d38cae7836cb1c","mode":"k","title":"发展现代化都市圈与城镇协调发展","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["现代化都市圈"],"qs":["政治理论必刷100题#27"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["regional"],"主类":["制度与规则"],"出处性质":["专项题干","机构注释"],"学科":["政治理论","社会治理"],"来源主题":["农业与城乡治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"2025年政府工作报告提出，发展现代化都市圈、优化空间格局，提升超大特大城市现代化治理水平，促进大中小城市和小城镇协调发展。","review":{"definition":"2025年政府工作报告提出，发展现代化都市圈、优化空间格局，提升超大特大城市现代化治理水平，促进大中小城市和小城镇协调发展。","explanation":"报告把都市圈建设和空间格局优化与不同规模城市、小城镇的协调发展纳入同一部署。第27题④列举了其中的发展现代化都市圈、优化空间格局和促进各类城镇协调发展的要求，表述正确。","references":[],"evidence":"发展现代化都市圈、优化空间格局，促进大中小城市和小城镇协调发展","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"cbe2b045c4cc446b","label":"现代化都市圈","topic":"农业与城乡治理","category":"非时政","text":"1.现代化都市圈\n城市群是新型城镇化主体形态，是支撑全国经济增长、促进区域协调发展、参与国际竞\n争合作的重要平台。都市圈是城市群内部以超大特大城市或辐射带动功能强的大城市为中\n心、以 1 小时通勤圈为基本范围的城镇化空间形态。\n坚持以供给侧结构性改革为主线，坚持市场化改革、扩大高水平开放，以促进中心城市\n与周边城市（镇）同城化发展为方向，以创新体制机制为抓手，以推动统一市场建设、基\n础设施一体高效、公共服务共建共享、产业专业化分工协作、生态环境共保共治、城乡融合\n发展为重点，培育发展一批现代化都市圈，形成区域竞争新优势，为城市群高质量发展、经\n济转型升级提供重要支撑。\n到 2022 年，都市圈同城化取得明显进展，基础设施一体化程度大幅提高，阻碍生产要\n素自由流动的行政壁垒和体制机制障碍基本消除，成本分担和利益共享机制更加完善，梯次\n形成若干空间结构清晰、城市功能互补、要素流动有序、产业分工协调、交通往来顺畅、\n公共服务均衡、环境和谐宜居的现代化都市圈。到 2035 年，现代化都市圈格局更加成熟，\n形成若干具有全球影响力的都市圈。\n——《国家发展改革委关于培育发展现代化都市圈的指导意见》","source":{"doc":"6cbfb01fe723bba64b75","first":9,"last":9,"page":9,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#27":{"paper":"政治理论必刷100题","n":27,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",8],"asrc":["国省考政治理论必刷100题.pdf",48],"card":"46fbb8f5881a8468bfaa2772","links":[{"id":"k-62d38cae7836cb1c","role":"直接考查","why":"发展现代化都市圈的政策要求包括优化空间格局和促进各类城镇协调发展。"}]}},"terms":{},"references":{},"topics":[{"slug":"regional","title":"区域协调与城乡融合"}],"units":{"k-62d38cae7836cb1c":[["政治理论必刷100题#27"]]}};
